// Ownership stays persistent; the bag contains only unequipped copies.
const EQUIPMENT_LAYOUT=[['helmet','Miğfer'],['earring','Küpe'],['sword','Silah'],['chest','Zırh'],['shield','Kalkan'],['gloves','Eldiven'],['boots','Ayakkabı'],['accessory','Tılsım']];
function equippedItem(slot){return slot==='sword'?(p.sword?'sword:'+p.sword:null):slot==='accessory'?p.accessory:p.equipment[slot]||null}
function itemSlot(id){return id?.startsWith('sword:')?'sword':GEAR[id]?.slot|| (ITEMS[id]?.kind==='accessory'?'accessory':null)}
function bagItemCount(id){return Math.max(0,itemCount(id)-(isEquipped(id)?1:0))}
function bagItems(){return allOwnedItems().filter(id=>bagItemCount(id)>0)}
function removeEquipment(slot){if(activeSwing)return false;const id=equippedItem(slot);if(!id)return false;if(slot==='sword'){p.sword=null;p.weapon=0}else if(slot==='accessory'){equipAccessory(id);return true}else p.equipment[slot]=null;selectedInventoryId=id;save();ui();toast(itemInfo(id).name+' çantaya döndü.');return true}
function equipIntoSlot(id,slot){if(itemSlot(id)!==slot||!itemCount(id)||isEquipped(id)||activeSwing)return false;return activateItem(id)}
function equipmentPanelHTML(){return `<aside class="paperdoll"><div class="doll-heading"><small>EKİPMAN</small><b>Gezgin <span>Sv.${p.level}</span></b></div><div class="equipment-board"><div class="body-etching" aria-hidden="true"><i></i></div><canvas id="bagHero" width="200" height="210" aria-label="Taktığın ekipmanlarla karakter önizlemesi"></canvas>${EQUIPMENT_LAYOUT.map(([slot,label])=>{const id=equippedItem(slot),info=itemInfo(id);return `<button class="body-slot pos-${slot} ${id?'occupied':''} ${selectedInventoryId===id&&id?'selected':''}" data-equip-slot="${slot}" ${id?'draggable="true"':''} title="${label}: ${info?.name||'Boş'}${id?' · Çift tık: çıkar':''}" aria-label="${label}: ${info?.name||'Boş yuva'}"><span class="slot-engraving" aria-hidden="true">${{helmet:'♜',earring:'◉',sword:'⚔',chest:'♙',shield:'⛨',gloves:'✋',boots:'♟',accessory:'◇'}[slot]}</span>${id?itemIconHTML(id):''}<small>${label}</small></button>`}).join('')}</div><div class="gear-stats"><span>⚔ <b>${damage()}</b> Hasar</span><span>⛨ <b>${p.armor*2+(accessoryStats().armor||0)}</b> Savunma</span><span>♥ <b>${Math.ceil(p.hp)} / ${p.maxHp}</b></span></div><p class="fine">Kuşanmak için eşyayı doğru yuvaya sürükle veya çift tıkla. Çıkarmak için dolu yuvaya çift tıkla.</p></aside>`}
const BAG_PAGE_SIZE=30;let inventoryPage=0,inventorySearch='',inventorySort='type';
function filteredBagItems(){const term=inventorySearch.toLocaleLowerCase('tr');return bagItems().filter(id=>(inventoryFilter==='all'||itemInfo(id).kind===inventoryFilter)&&itemInfo(id).name.toLocaleLowerCase('tr').includes(term)).sort((a,b)=>inventorySort==='name'?itemInfo(a).name.localeCompare(itemInfo(b).name,'tr'):inventorySort==='rarity'?itemRarity(b).rank-itemRarity(a).rank:inventorySort==='quantity'?bagItemCount(b)-bagItemCount(a):itemInfo(a).kind.localeCompare(itemInfo(b).kind)||itemInfo(a).name.localeCompare(itemInfo(b).name,'tr'))}
function inventoryPageCount(){return Math.max(4,Math.ceil(filteredBagItems().length/BAG_PAGE_SIZE))}
function changeBagPage(page){inventoryPage=Math.max(0,Math.min(inventoryPageCount()-1,page));renderInventory()}
renderInventory=function(){const owned=bagItems(),filtered=filteredBagItems(),pages=inventoryPageCount();inventoryPage=Math.max(0,Math.min(pages-1,inventoryPage));const items=filtered.slice(inventoryPage*BAG_PAGE_SIZE,(inventoryPage+1)*BAG_PAGE_SIZE);if(!itemInfo(selectedInventoryId)||!itemCount(selectedInventoryId)||(!filtered.includes(selectedInventoryId)&&!isEquipped(selectedInventoryId)))selectedInventoryId=items[0]||null;const tabs=[['all','Tümü'],['sword','Silah'],['gear','Ekipman'],['accessory','Takı'],['consumable','İksir'],['material','Malzeme'],['trophy','Ganimet']];
 $('bagContents').innerHTML=`<div class="equipment-inventory">${equipmentPanelHTML()}<section class="inventory-storage"><div class="inventory-topline"><span>◆ ${p.gold} altın</span><span>${owned.length} / ${pages*BAG_PAGE_SIZE} slot · Sayfa ${inventoryPage+1}/${pages}</span></div><div class="bag-tools"><label>Eşya ara<input id="bagSearch" type="search" placeholder="Adıyla ara, Enter’a bas" aria-label="Çantada eşya ara"></label><label>Sırala<select id="bagSort" aria-label="Eşyaları sırala"><option value="type">Türüne göre</option><option value="name">Ada göre</option><option value="rarity">Nadirliğe göre</option><option value="quantity">Adedine göre</option></select></label></div><div class="inventory-tabs">${tabs.map(([id,t])=>`<button data-filter="${id}" class="${inventoryFilter===id?'selected':''}">${t}</button>`).join('')}</div><nav class="bag-pagination" aria-label="Çanta sayfaları"><button data-page="${inventoryPage-1}" ${inventoryPage===0?'disabled':''} aria-label="Önceki sayfa">‹</button>${Array.from({length:pages},(_,n)=>`<button data-page="${n}" class="${inventoryPage===n?'selected':''}" aria-label="Çanta sayfa ${n+1}">${n+1}</button>`).join('')}<button data-page="${inventoryPage+1}" ${inventoryPage===pages-1?'disabled':''} aria-label="Sonraki sayfa">›</button><span>${filtered.length} eşya türü</span></nav><div class="bag-layout"><div class="bag-drop-area">${!items.length?`<div class="bag-empty">${filtered.length?'Bu sayfa boş. Diğer sayfalara göz atabilirsin.':'Bu filtrede eşya yok. Aramayı veya kategoriyi değiştirebilirsin.'}</div>`:''}<div class="bag-grid">${items.map(id=>`<button class="bag-slot rarity-${itemRarity(id).id} ${selectedInventoryId===id?'selected':''}" draggable="true" data-item="${id}" title="${itemInfo(id).name}" aria-label="${itemInfo(id).name}, çantada ${bagItemCount(id)} adet">${itemIconHTML(id)}<b class="stack-count">${bagItemCount(id)}</b><span class="item-short-name">${itemInfo(id).name}</span><span class="rarity-dot" title="${itemRarity(id).name}"></span></button>`).join('')+Array.from({length:Math.max(0,BAG_PAGE_SIZE-items.length)},()=>'<span class="bag-slot empty"></span>').join('')}</div><p class="fine">Kuşanılan eşya soldaki yuvaya taşınır. Silah veya iksir seç; alttaki slota tıklayarak ekle.</p></div><section id="inventoryDetail"></section></div></section></div>`;
 const root=$('bagContents');$('bagSearch').value=inventorySearch;$('bagSort').value=inventorySort;$('bagSearch').onchange=()=>{inventorySearch=$('bagSearch').value.trim();inventoryPage=0;selectedInventoryId=null;renderInventory()};$('bagSearch').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();$('bagSearch').onchange()}};$('bagSort').onchange=()=>{inventorySort=$('bagSort').value;inventoryPage=0;renderInventory()};root.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>changeBagPage(Number(b.dataset.page)));root.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{inventoryFilter=b.dataset.filter;inventoryPage=0;selectedInventoryId=null;renderInventory()});root.querySelectorAll('[data-item]').forEach(b=>{const id=b.dataset.item;b.onclick=()=>selectInventoryItem(id);b.ondblclick=()=>{if(itemSlot(id))activateItem(id);else if(itemInfo(id).kind==='consumable')activateItem(id);renderInventory()};b.ondragstart=e=>{selectedInventoryId=id;e.dataTransfer.setData('text/plain',id);e.dataTransfer.effectAllowed='move'}});
 root.querySelectorAll('[data-equip-slot]').forEach(b=>{const slot=b.dataset.equipSlot,id=equippedItem(slot);b.onclick=()=>{if(id){selectInventoryItem(id)}else{inventoryPage=0;inventoryFilter=slot==='sword'?'sword':slot==='accessory'?'accessory':'gear';selectedInventoryId=null;renderInventory()}};b.ondblclick=()=>{removeEquipment(slot);renderInventory()};b.ondragstart=e=>{if(!id)return;e.dataTransfer.setData('text/plain',id);e.dataTransfer.effectAllowed='move'};b.ondragover=e=>{e.preventDefault();b.classList.add('drop-hover')};b.ondragleave=()=>b.classList.remove('drop-hover');b.ondrop=e=>{e.preventDefault();const item=e.dataTransfer.getData('text/plain');if(!equipIntoSlot(item,slot))toast('Bu eşya '+(GEAR_SLOTS[slot]||'Kılıç')+' yuvasına uygun değil veya zaten kuşanılmış.');renderInventory()}});
 root.querySelectorAll('.bag-drop-area').forEach(area=>{area.ondragover=e=>e.preventDefault();area.ondrop=e=>{e.preventDefault();const id=e.dataTransfer.getData('text/plain');if(isEquipped(id))removeEquipment(itemSlot(id));renderInventory()}});paintItemIcons(root);renderInventoryDetail();renderQuickbar();
};
renderInventoryDetail=function(){const id=selectedInventoryId,i=itemInfo(id);if(!i){$('inventoryDetail').innerHTML='<p class="fine">Bir çanta eşyası veya dolu ekipman yuvası seç.</p>';return}const slot=itemSlot(id),equipped=isEquipped(id),usable=slot||i.kind==='consumable';$('inventoryDetail').innerHTML=`<div class="detail-icon">${itemIconHTML(id,true)}</div><small>${itemRarity(id).name.toLocaleUpperCase('tr')} · ${equipped?'KUŞANILMIŞ · ':''}${slot?(GEAR_SLOTS[slot]|| (slot==='sword'?'Silah':'Tılsım')):i.kind==='trophy'?'BOSS GANİMETİ':'ÇANTA EŞYASI'}</small><h3 style="color:${i.color}">${i.name}</h3><p>${i.description}</p><p class="fine">${equipped?'Karakter üzerinde':'Çantada: '+bagItemCount(id)}${i.level?' · Sv.'+i.level:''}</p>${usable?`<button id="inventoryUse" ${!equipped&&i.level&&p.level<i.level?'disabled':''}>${equipped?'Çıkar → Çantaya':slot?'Kuşan → Yuvaya':'Kullan'}</button>`:''}<h4>Hızlı slota ata</h4><div class="assign-slots">${p.quickSlots.map((v,n)=>`<button data-assign="${n}" class="${v===id?'selected':''}">${n+1}</button>`).join('')}</div>`;if($('inventoryUse'))$('inventoryUse').onclick=()=>{if(equipped)removeEquipment(slot);else activateItem(id);renderInventory()};$('inventoryDetail').querySelectorAll('[data-assign]').forEach(b=>b.onclick=()=>assignQuickSlot(Number(b.dataset.assign),id));paintItemIcons($('inventoryDetail'));
};
// Small equipment illustrations share the world sprite palette, never emoji overlays.
const regularItemIconHTML=itemIconHTML;itemIconHTML=function(id,large=false){if(GEAR[id])return `<canvas class="gear-icon" data-gear-icon="${id}" width="48" height="56" aria-label="${GEAR[id].name}"></canvas>`;return regularItemIconHTML(id,large)};
const paintRegularIcons=paintItemIcons;paintItemIcons=function(root){paintRegularIcons(root);root.querySelectorAll('[data-gear-icon]').forEach(c=>paintGearIcon(c,c.dataset.gearIcon))};
function paintGearIcon(c,id){const q=GEAR[id];if(!q)return;const{g,R,P}=spriteTools(c),ember=id.startsWith('ember'),metal=ember?'#c38d60':q.color,light=ember?'#f0c48d':'#dce7df',dark='#2a3c4a';g.clearRect(0,0,48,56);
 if(q.slot==='helmet'){const previous=p.equipment;try{p.equipment={...previous,helmet:id};g.drawImage(helmetSprite('down',id),0,4)}finally{p.equipment=previous}}
 else if(q.slot==='chest'){P([[7,12],[17,7],[22,13],[28,13],[33,7],[43,13],[39,22],[35,19],[35,42],[14,42],[14,20],[10,23]],dark);P([[11,14],[17,11],[22,17],[28,17],[33,11],[39,15],[36,19],[32,17],[32,37],[24,43],[17,36],[17,17],[13,19]],metal);R(20,19,3,16,light);R(17,39,17,3,'#8f6b47');R(23,38,5,5,light)}
 else if(q.slot==='shield'){P(ember?[[24,5],[40,12],[42,29],[34,43],[24,49],[14,43],[6,29],[8,12]]:[[24,5],[41,13],[37,35],[24,51],[11,35],[7,13]],dark);P([[24,9],[37,15],[34,34],[24,45],[14,34],[11,15]],metal);P([[24,14],[31,19],[29,32],[24,38],[19,32],[17,19]],ember?'#733b3e':'#365b79');R(22,18,4,18,light);R(17,24,14,4,light)}
 else if(q.slot==='boots'){for(const x of [7,27]){R(x,10,12,23,dark);R(x+2,12,8,16,metal);R(x+2,14,7,3,light);P([[x,31],[x+11,31],[x+14,39],[x+14,44],[x-2,44],[x-2,39]],dark);R(x,34,11,6,metal);R(x-1,41,14,2,light)}}
 else if(q.slot==='gloves'){for(const x of [5,27]){R(x,12,15,8,dark);R(x+2,13,11,5,metal);R(x+3,14,8,2,light);P([[x+2,20],[x+13,20],[x+16,29],[x+13,40],[x+2,40],[x-1,29]],dark);R(x+3,22,9,12,metal);for(let k=0;k<3;k++)R(x+3+k*3,31,2,6,light)}}
 else{P([[24,10],[33,17],[30,28],[24,33],[18,28],[15,17]],'#b99c63');P([[24,13],[29,18],[27,24],[24,27],[21,24],[19,18]],metal);R(22,32,4,8,light);P([[24,37],[30,43],[24,50],[18,43]],metal)}
}

function drawEquippedBoot(g,id){const {R,P}=spriteTools({getContext:()=>g}),ember=id==='emberBoots',starter=id==='travelerBoots';R(-4,0,9,13,'#1c2935');if(!id){R(-3,1,7,7,'#52616a');R(-5,10,11,7,'#614a38');R(-4,11,9,2,'#9b7b52');return}const c=ember?'#b87b54':starter?'#71869a':GEAR[id]?.color||'#a4b8bd';R(-4,1,8,7,c);R(-3,2,6,2,ember?'#edb980':'#dde5dd');R(-5,10,12,7,'#202c39');P([[-4,10],[3,10],[6,13],[6,15],[-4,15]],c);R(-4,15,11,2,'#25333b');R(-3,11,6,2,ember?'#efb474':'#d8dfd4');if(ember){R(-5,0,2,5,'#d8a067');R(3,0,2,5,'#d8a067')}}

function selectInventoryItem(id){selectedInventoryId=id;const root=$('bagContents');root.querySelectorAll('[data-item]').forEach(b=>b.classList.toggle('selected',b.dataset.item===id));root.querySelectorAll('[data-equip-slot]').forEach(b=>b.classList.toggle('selected',equippedItem(b.dataset.equipSlot)===id));renderInventoryDetail()}
